{
  "version": "1.1.0",
  "settings": {
    "model": "anthropic.claude-sonnet-4-6",
    "maxTokens": 64000,
    "temperature": 0,
    "engine": "basic-v2",
    "maxIterations": 3,
    "mode": "standard"
  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "start__output__emailSubject": {
        "type": "string",
        "description": "The subject line of the inbound support email"
      },
      "start__output__emailBody": {
        "type": "string",
        "description": "The full body text of the inbound support email"
      },
      "start__output__emailFrom": {
        "type": "string",
        "description": "The sender email address of the inbound support email"
      }
    }
  },
  "outputSchema": {
    "type": "object",
    "properties": {
      "category": {
        "type": "string",
        "description": "Support category: billing, technical, account, general, or other"
      },
      "priority": {
        "type": "string",
        "description": "Priority level: critical, high, medium, or low"
      }
    },
    "required": ["category", "priority"]
  },
  "metadata": {
    "storageVersion": "50.0.0",
    "isConversational": false,
    "showProjectCreationExperience": false
  },
  "type": "lowCode",
  "guardrails": [],
  "messages": [
    {
      "role": "system",
      "content": "You are a support email triage specialist. Your sole task is to classify inbound support emails into a category and priority level based on their subject, body, and sender.\n\nCategories:\n- billing: payment, invoice, charge, refund, subscription, pricing\n- technical: error, bug, crash, not working, performance, integration, API\n- account: login, password, access, permissions, user management, security\n- general: feature request, feedback, question, how-to, documentation\n- other: anything that does not fit the above\n\nPriority levels:\n- critical: system down, data loss, security breach, production outage affecting the customer business\n- high: significant feature broken, blocking customer workflow, SLA risk\n- medium: partial degradation, workaround exists, non-blocking issue\n- low: cosmetic issue, general question, feature request, low urgency\n\nClassification rules:\n1. Read the subject, body, and sender domain carefully before deciding.\n2. Choose exactly ONE category and ONE priority level.\n3. Base priority on business impact described in the email, not on tone or politeness.\n4. For ambiguous emails, default to the category most aligned with the primary complaint.\n5. Respond ONLY with a valid JSON object matching the required output schema — no explanation, no markdown fencing, no extra text.\n\nExpected output format:\n{\"category\": \"<billing|technical|account|general|other>\", \"priority\": \"<critical|high|medium|low>\"}",
      "contentTokens": [
        {
          "type": "simpleText",
          "rawString": "You are a support email triage specialist. Your sole task is to classify inbound support emails into a category and priority level based on their subject, body, and sender.\n\nCategories:\n- billing: payment, invoice, charge, refund, subscription, pricing\n- technical: error, bug, crash, not working, performance, integration, API\n- account: login, password, access, permissions, user management, security\n- general: feature request, feedback, question, how-to, documentation\n- other: anything that does not fit the above\n\nPriority levels:\n- critical: system down, data loss, security breach, production outage affecting the customer business\n- high: significant feature broken, blocking customer workflow, SLA risk\n- medium: partial degradation, workaround exists, non-blocking issue\n- low: cosmetic issue, general question, feature request, low urgency\n\nClassification rules:\n1. Read the subject, body, and sender domain carefully before deciding.\n2. Choose exactly ONE category and ONE priority level.\n3. Base priority on business impact described in the email, not on tone or politeness.\n4. For ambiguous emails, default to the category most aligned with the primary complaint.\n5. Respond ONLY with a valid JSON object matching the required output schema — no explanation, no markdown fencing, no extra text.\n\nExpected output format:\n{\"category\": \"<billing|technical|account|general|other>\", \"priority\": \"<critical|high|medium|low>\"}"
        }
      ]
    },
    {
      "role": "user",
      "content": "From: {{input.start__output__emailFrom}}\nSubject: {{input.start__output__emailSubject}}\n\n{{input.start__output__emailBody}}",
      "contentTokens": [
        {
          "type": "simpleText",
          "rawString": "From: "
        },
